package main

import "fmt"

// 演示 slice 共享底层数组与 append 扩容分离
func appendInPlace(s []int) {
	s[0] = 99          // 写入共享底层数组，调用方可见
	s = append(s, 100) // len=2, cap=3，未扩容，写到底层数组下标 2
}

func appendDetached(s []int) {
	s = append(s, 200) // len=2, cap=2，触发 growslice，局部 header 指向新数组
}

// 演示 typed nil 陷阱
type MyErr struct{ Code int }

func (e *MyErr) Error() string { return fmt.Sprintf("code=%d", e.Code) }

func returnsTypedNil() error {
	var p *MyErr // nil
	return p     // bug: error 接口的 itab 非 nil
}

func returnsProperNil() error {
	var p *MyErr
	if p == nil {
		return nil // 正确: 显式返回 nil，接口 itab 和 data 都为 nil
	}
	return p
}

func main() {
	// slice 共享示例
	nums := []int{1, 2, 3}          // len=3, cap=3
	appendInPlace(nums[:2])          // nums[:2] 的 cap=3（继承原数组剩余空间）
	fmt.Println("after InPlace:", nums) // [99 2 100] —— 底层数组被修改

	other := []int{1, 2, 3}
	appendDetached(other[:2:2])       // 三下标切片: len=2, cap=2，强制限制 cap
	fmt.Println("after Detached:", other) // [1 2 3] —— 不变，append 结果只在局部

	// typed nil 陷阱
	err1 := returnsTypedNil()
	err2 := returnsProperNil()
	fmt.Println("typed nil == nil?", err1 == nil) // false —— itab 非 nil
	fmt.Println("proper nil == nil?", err2 == nil) // true
}
